            for fallback in ["nouser", "nopassword", "nohost", "nodb"]
        ):
            # Valid URI - cache it and return
            self._db_uri_cache = uri
            return uri
        # Return the fallback value without caching
        # This allows retry on next access when config might be ready
        return uri
